/**
 * One person on their flow as the step card and the nudges take them (`flows/nudges.ts`'s `PersonFlow`), from the rows
 * the app keeps: their flow rows (`flow_rows`, read by `load.ts`), the holds and the reminders sent (`nudge_holds`,
 * `nudge_sent`), their step notes (team lines in `messages` with a `step_key`), their thread's last lines, what we owe
 * them (cut 2's `contact_owed`) and what their page says they opened (cut 8's read-back). Pure.
 */
import type { PaperId } from './facts.ts'
import { candidateStampsFor } from './candidateLoad.ts'
import { subStampsWithOnboarding } from './subOnboardingLoad.ts'
import { flowStampsFor, type FlowRows } from './load.ts'
import type { NudgeMark, PersonFlow, PortalRead, StepNote } from './nudges.ts'
import { quietDays as quietDaysOf, readFlow, type FlowDef } from './state.ts'

/** `nudge_holds`, standing or let go. A residential customer's job is a Pipeline job, on `jobs_ledger_id` (v2.6007). */
export type HoldRow = { id?: string; step_key: string; project_id: string | null; jobs_ledger_id?: string | null; until_on: string; released_at: string | null }
/** `nudge_sent`: a reminder a person sent with Remind now, or the app sent by itself. The job as a hold's. */
export type SentRow = { step_key: string; project_id: string | null; jobs_ledger_id?: string | null; sent_at: string; sent_by: 'person' | 'app' }
/** The job a hold or a reminder sits on: a GC project, or a residential customer's Pipeline job (v2.6007). */
export const jobOfMark = (r: { project_id: string | null; jobs_ledger_id?: string | null }): string | null => r.project_id ?? r.jobs_ledger_id ?? null
/** A step's team note: a `messages` line with its `step_key`. */
export type StepNoteRow = { step_key: string; project_id: string | null; who_user_id: string | null; body: string; at: string }
/** The least of a thread line the card reads: whose it is and when. */
export type ThreadLineRow = { direction: 'in' | 'out' | 'team'; at: string }
/** Cut 2's `contact_owed` (`ContactOwedRow` in `followUp/followUpRows.ts`): whose it is and whether it is done. */
export type OwedRow = { contact_id: string; done_at: string | null }
/** A paper on a customer's page as cut 8's read-back gives it (`PaperView` in `portal/papers.ts`). */
export type PortalPaperRow = { kind: 'contract' | 'changeOrder' | 'payApp'; title: string; sentAt: string; answered: boolean; viewedAt: string | null }
/** A customer's page as cut 8's read-back gives it (`CustomerReadBack`): its last open and every paper sent. */
export type PortalReadBackRow = { lastOpenedAt: string | null; papers: readonly PortalPaperRow[] }

export type PersonInputs = {
  /** The contact's id. */
  id: string
  /** What we call them (the spine's `firstName`). */
  first: string
  flow: FlowDef
  rows: FlowRows
  now: Date
  holds?: readonly HoldRow[]
  sent?: readonly SentRow[]
  notes?: readonly StepNoteRow[]
  lines?: readonly ThreadLineRow[]
  /** `contact_owed` rows, theirs or everyone's: we owe them while one of theirs is not done. */
  owed?: readonly OwedRow[]
  /** A customer's page as cut 8 reads it back; unset for anyone else. */
  portal?: PortalReadBackRow | null
}

/** `gc_paper_sends.paper` in the flow's paper words. */
const SENT_PAPER: Readonly<Record<string, PaperId>> = { msa: 'msa', sow: 'sow', insurance: 'coi', w9: 'w9', waiver: 'waiver' }

const newestAt = <T extends { at: string }>(xs: readonly T[]): T | null => xs.reduce<T | null>((b, x) => (!b || x.at > b.at ? x : b), null)

/** Each step's Hold until and its last Remind now, one mark per step and job. The app's own reminders are no press. */
export function marksFrom(holds: readonly HoldRow[], sent: readonly SentRow[]): NudgeMark[] {
  const marks = new Map<string, NudgeMark>()
  const at = (stepId: string, jobId: string | null) => {
    const key = `${stepId}|${jobId ?? ''}`
    const m = marks.get(key) ?? { stepId, jobId }
    marks.set(key, m)
    return m
  }
  for (const h of holds) if (!h.released_at) at(h.step_key, jobOfMark(h)).holdUntil = h.until_on
  for (const s of sent) {
    if (s.sent_by !== 'person') continue
    const m = at(s.step_key, jobOfMark(s))
    if (!m.nudgedAt || s.sent_at > m.nudgedAt) m.nudgedAt = s.sent_at
  }
  return [...marks.values()]
}

/** Each paper of ours that went to them, its sends in order, the first and then each reminder. */
export function sendsFrom(rows: FlowRows): Partial<Record<PaperId, readonly string[]>> {
  const out: Partial<Record<PaperId, string[]>> = {}
  for (const s of rows.paperSends ?? []) {
    const paper = SENT_PAPER[s.paper]
    if (!paper) continue
    ;(out[paper] ??= []).push(s.created_at || s.sent_on)
  }
  for (const k of Object.keys(out) as PaperId[]) out[k]?.sort()
  return out
}

/** Whether we owe them: one of their `contact_owed` rows is not done. */
export const oweFrom = (contactId: string, owed: readonly OwedRow[]): boolean => owed.some((r) => r.contact_id === contactId && r.done_at == null)

/** The read-back's kinds in the flow's paper words. */
const VIEW_PAPER: Readonly<Record<PortalPaperRow['kind'], PaperId>> = { contract: 'contract', changeOrder: 'co', payApp: 'payapp' }

/** The paper that went last; of two sent the same day, the later in the read-back's order. */
const newestSent = (papers: readonly PortalPaperRow[]): PortalPaperRow | null => papers.reduce<PortalPaperRow | null>((b, p) => (!b || p.sentAt >= b.sentAt ? p : b), null)

/**
 * What their page says they opened, from cut 8's read-back: when they opened each kind's newest paper sent, and the
 * newest change order they have not answered. A customer who never opened their page opened nothing, and a change
 * order still waits on them.
 */
export function portalFrom(back: PortalReadBackRow | null | undefined): PortalRead | null {
  if (!back) return null
  const views: Partial<Record<PaperId, string>> = {}
  if (back.lastOpenedAt)
    for (const kind of Object.keys(VIEW_PAPER) as PortalPaperRow['kind'][]) {
      const seen = newestSent(back.papers.filter((p) => p.kind === kind))?.viewedAt
      if (seen) views[VIEW_PAPER[kind]] = seen
    }
  const open = newestSent(back.papers.filter((p) => p.kind === 'changeOrder' && !p.answered))
  return { views, openChange: open ? { name: open.title } : null }
}

/** Whose court their thread is in: ours after their last word, theirs after ours, nobody's with no line yet. */
export function courtFrom(lines: readonly ThreadLineRow[]): 'ours' | 'theirs' | null {
  const lastIn = newestAt(lines.filter((l) => l.direction === 'in'))
  const lastOut = newestAt(lines.filter((l) => l.direction === 'out'))
  if (!lastIn && !lastOut) return null
  if (!lastOut || (lastIn && lastIn.at > lastOut.at)) return 'ours'
  return 'theirs'
}

/** One person on their flow, for the panel, the card and the nudges. */
export function personFlowFrom(i: PersonInputs): PersonFlow {
  // A candidate's stamps come from their hiring board row (spike); everyone else's from the flow rows.
  const stamps =
    i.flow.kind === 'candidate'
      ? candidateStampsFor(i.rows)
      : i.flow.kind === 'sub'
        ? subStampsWithOnboarding(flowStampsFor('sub', i.rows, i.now), i.rows, i.lines ?? [], i.now)
        : flowStampsFor(i.flow.kind, i.rows, i.now)
  const reading = readFlow(i.flow, stamps, i.now)
  const names = i.rows.userNames ?? {}
  const lines = i.lines ?? []
  const notes: StepNote[] = (i.notes ?? []).map((n) => ({
    stepId: n.step_key,
    jobId: n.project_id,
    by: (n.who_user_id && names[n.who_user_id]) || '',
    text: n.body,
    at: n.at,
  }))
  const jobs: Partial<Record<string, string>> = {}
  for (const p of i.rows.projects ?? []) {
    const name = (p as { name?: string | null }).name
    if (name) jobs[p.project_id] = name
  }
  return {
    id: i.id,
    first: i.first,
    flow: i.flow,
    reading,
    quietDays: quietDaysOf(lines, i.now),
    lastOutAt: newestAt(lines.filter((l) => l.direction === 'out'))?.at ?? null,
    court: courtFrom(lines),
    owe: oweFrom(i.id, i.owed ?? []),
    marks: marksFrom(i.holds ?? [], i.sent ?? []),
    notes,
    jobs,
    sends: sendsFrom(i.rows),
    portal: portalFrom(i.portal),
  }
}
